const promptBuilder = new PromptBuilder({
  identity: 'You are HAL.',
  responseGuidelines: 'Be precise.',
});

describe('beforeSession throwing', () => {
  it('runs onError and afterSession when beforeSession throws', async () => {
    const errorToThrow = new Error('Database connection failed in beforeSession');

    let caughtError: Error | undefined;
    let afterSessionRan = false;

    const orchestrator = createChatOrchestrator(createMockProvider('hello back'), promptBuilder, undefined, {
      hooks: {
        beforeSession: async () => {
          throw errorToThrow;
        },
        onError: async (_session, error) => {
          caughtError = error;
        },
        afterSession: async () => {
          afterSessionRan = true;
        },
      },
    });

    const call = orchestrator.processMessage(createSession('hello'));
    const rejectionMessage = await call
      .then(() => undefined)
      .catch((error: unknown) => (error instanceof Error ? error.message : String(error)));

    expect({
      rejectionMessage,
      caughtSameError: caughtError === errorToThrow,
      afterSessionRan,
    }).toEqual({
      rejectionMessage: 'Database connection failed in beforeSession',
      caughtSameError: true,
      afterSessionRan: true,
    });
  });
});

